def classify_triangle(a, b, c):
    # return "invalid" if any side is zero or negative.
    if a &lt;= 0 or b &lt;= 0 or c &lt;= 0:
        return "invalid"

    # return "invalid" if the sides can't form a triangle. 
    if a + b &lt;= c or a + c &lt;= b or b + c &lt;= a:
        return "invalid"

    # "equilateral" — all three sides are equal
    if a == b == c:
        return "equilateral"

    # "isosceles" — exactly two sides are equal
    if (a == b and b != c) or (a == c and b != a) or (c == b and c != a):
        return "isosceles"

    return "scalene"

