Bogo Sort
Bogo sort: Orders a list of values by repetitively shuﬀeling them and checking if they are sorted.
Name comes from “bogus”

import random

def is_sorted(lst):
    for i in range(len(lst)-1):
        if lst[i] &gt; lst[i+1]:
            return False
    return True

def bogo_sort(lst):
    while not is_sorted(lst):
        random.shuffle(lst)
    return lst

