Selection Sort – implementation

def selection_sort(lst):
    for i in range(len(lst) - 1):
        # Find index of smallest
        small = i
        for j in range(i + 1, len(lst)):
            if lst[j] &lt; lst[small]:
                small = j
        # Swap smallest into place
        lst[i],lst[small] = lst[small],lst[i]

