Merge

def merge (left, right):
  center = []
  l = 0
  r = 0

  while l &lt; len(left) and r &lt; len(right):
    if left [l] &lt; right [r]:
      center.append(left[l])
      l += 1
    else:
      center.append(right[r])
      r += 1

  while l &lt; len(left):
    center.append(left[l])
    l += 1

  while r &lt; len(right):
    center.append(right[r])
    r += 1

  return center

Merge sort
Class “divide and conquer” algorithm

def merge_sort(lst):
    if len(lst) == 1:
        return lst
    else:
        mid = len(lst)//2
        left = lst[:mid]
        right = lst[mid:]

        left = merge_sort(left)
        right = merge_sort(right)

        return merge(left, right)

